const api=window.bench;
// Mirrors HistoryPanel's copy: NaN and Infinity have toLocaleString() representations
// ("NaN", "∞") that would otherwise be rendered straight into the run preview.
const number=(n:number|null|undefined,d=1)=>typeof n!=='number'||!Number.isFinite(n)?'—':n.toLocaleString(undefined,{maximumFractionDigits:d});
const toggle=(list:string[],id:string)=>list.includes(id)?list.filter(x=>x!==id):[...list,id];
// An <input type="number"> reports '' both for an empty box and for partially typed
// text, and +'' is 0. Writing that 0 through turned "clear the field to retype it"
// into a real setting, silently and with no way to tell from the box.
const numOr=(raw:string,previous:number)=>raw.trim()===''||!Number.isFinite(Number(raw))?previous:Number(raw);
const modelLabel=(m:Model)=>`${m.nativeMtp?.supported===true?'MTP · ':''}${m.display_name} · ${m.quantization?.name??'Unknown quantization'}${m.capabilities&&'vision' in m.capabilities&&m.capabilities.vision?' · Vision':''}`;
function Badge({children,tone=''}:{children:React.ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
// Field renders a <label>, which is right for one control and wrong for a set of them.
// A <label> inside a <label> is invalid, and the outer one binds to the first labelable
// descendant: clicking the caption "Models" toggled the first model's checkbox, and a
// screen reader announced that checkbox as "Models" rather than by the model's name.
// Same DOM shape otherwise, so the .field styling is unchanged.
function FieldGroup({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){
 const id=React.useId();
 return <div className="field" role="group" aria-labelledby={id}><span id={id}>{label}</span>{children}{hint&&<small>{hint}</small>}</div>;
}
function Empty({title,children}:{title:string;children:React.ReactNode}){return <div className="empty"><Activity size={34}/><h3>{title}</h3><p>{children}</p></div>}
function App(){
 const [libraryView,setLibraryView]=useState(()=>{try{return restoreLibraryView(JSON.parse(localStorage.getItem('lmb-library-view')||'null'));}catch{return {...defaultLibraryView};}});
 useEffect(()=>{try{localStorage.setItem('lmb-library-view',JSON.stringify(libraryView));}catch{}},[libraryView]);
 // The overview is the screen you open when you are not running anything, so which models and conditions you
 // last looked at survive a restart the same way the model library view does.
 const [historyView,setHistoryView]=useState(()=>{try{return restoreHistoryView(JSON.parse(localStorage.getItem('lmb-history-view')||'null'));}catch{return {...defaultHistoryView};}});
 useEffect(()=>{try{localStorage.setItem('lmb-history-view',JSON.stringify(historyView));}catch{}},[historyView]);
 const [resultsView,setResultsView]=useState<'run'|'overview'>(()=>{try{return localStorage.getItem('lmb-results-view')==='overview'?'overview':'run';}catch{return 'run';}});
 useEffect(()=>{try{localStorage.setItem('lmb-results-view',resultsView);}catch{}},[resultsView]);
 const [updateState,setUpdateState]=useState<UpdateState|null>(null),[showUpdate,setShowUpdate]=useState(false);
 useEffect(()=>{if(!api)return;api.updateState().then(setUpdateState).catch(()=>{});return api.onUpdate(setUpdateState);},[]);
 const [page,setPage]=useState('Models'),[snap,setSnap]=useState<Snapshot|null>(null),[models,setModels]=useState<Model[]>([]),[connected,setConnected]=useState(false),[connectionError,setConnectionError]=useState(''),[config,setConfig]=useState<RunConfig>(structuredClone(defaultConfig)),[busy,setBusy]=useState(''),[notice,setNotice]=useState(''),[error,setError]=useState(''),[progress,setProgress]=useState<Progress|null>(null),[runId,setRunId]=useState(''),[run,setRun]=useState<Run|null>(null),[editTest,setEditTest]=useState<TestCase|null>(null),[settingsDraft,setSettingsDraft]=useState<PublicSettings>(defaultPublicSettings),[tokenDraft,setTokenDraft]=useState(''),[clearToken,setClearToken]=useState(false),[sampleId,setSampleId]=useState('');
 const refresh=async()=>{const s=await api.snapshot();setSnap(s);setProgress(s.progress);return s;};
 const discover=async()=>{try{const m=await api.models();setModels(m);setConnected(true);setConnectionError('');return m;}catch(e){setConnected(false);setConnectionError((e as Error).message);return [];}};
 const act=async(name:string,fn:()=>Promise<unknown>)=>{setBusy(name);setError('');try{await fn();}catch(e){setError((e as Error).message);}finally{setBusy('');}};
 useEffect(()=>{if(!api){setError('Open this app through Local Model Bench.exe. The browser preview cannot access desktop features.');return;}refresh().then(s=>{setSettingsDraft(s.settings);setConfig(c=>({...c,timeoutSec:s.settings.timeoutSec}));if(s.runs[0])setRunId(s.runs[0].id);}).catch(e=>setError(e.message));discover();return api.onProgress(p=>{setProgress(p);if(p)setRunId(p.runId);else{refresh();discover();}});},[]);
 // A saved run cannot change on its own, so it is read once. Only the run that is actually progressing or
 // being graded keeps being re-read; a finished run carries every saved response, and re-reading it on a timer
 // moved megabytes across the process boundary to arrive at identical results.
 const liveRun=!!progress&&progress.runId===runId;
 useEffect(()=>{if(!runId||!api)return;let alive=true;const update=()=>api.getRun(runId).then(r=>{if(alive)setRun(r)}).catch(e=>{if(alive)setError(e.message)});update();if(!liveRun)return ()=>{alive=false;};const t=setInterval(update,2000);return ()=>{alive=false;clearInterval(t);};},[runId,liveRun]);
 // Removing an imported pack left the Run screen still pointing at it: the panel read
 // "Removed benchmark · 100 questions", which looks like a real selection, and Start
 // stayed enabled until validateBenchmark refused it with no hint about the cause.
 useEffect(()=>{if(config.benchmark&&snap&&!snap.packs.some(p=>p.id===config.benchmark!.packId))setConfig(c=>({...c,benchmark:undefined}));},[snap?.packs,config.benchmark?.packId]);
 const update=<K extends keyof RunConfig>(key:K,v:RunConfig[K])=>setConfig(c=>({...c,[key]:v,...(['waves','maxTokens'].includes(key)?{preset:'Custom'}:{})}));
 const started=async()=>{const id=await api.startRun(config);setRunId(id);setPage('Run');await refresh();};
 // Vision on appends the local image smoke test to whatever text tests are selected.
 const totalTests=(config.mode!=='quality'?config.performanceLengths.length:0)+(config.mode!=='performance'?(config.benchmark?.count??config.testIds.length):0)+(config.vision==='on'?visionTestIds.length:0);
 const total=config.modelKeys.length*totalTests*config.waves*config.concurrency.reduce((a,b)=>a+b,0);
 const allowedReasoning=reasoningOptions(models,config.modelKeys);
 const invalidReasoning=config.reasoning!=='default'&&!allowedReasoning.includes(config.reasoning);
 const visionMode=config.vision??'auto';
 const selectedModels=models.filter(m=>config.modelKeys.includes(m.key));
 const visionCapable=models.filter(m=>visionSupport(m).supported===true);
 const visionUnsupported=selectedModels.filter(m=>visionSupport(m).supported!==true);
 const visionBlocked=visionMode==='on'&&(!selectedModels.length||visionUnsupported.length>0);
 const shownModels=visibleModels(models,libraryView);
 const hiddenSelected=config.modelKeys.filter(id=>!shownModels.some(m=>m.key===id)).length;
 const selectedSample=run?.samples.find(s=>s.id===sampleId);
 const pages=[{name:'Models',icon:Boxes},{name:'Benchmarks',icon:BarChart3},{name:'Tests',icon:FlaskConical},{name:'Run',icon:Play},{name:'Results',icon:BarChart3},{name:'Settings',icon:SettingsIcon}];
 return <div className="app"><aside className="sidebar"><div className="brand"><div className="brandmark"><Activity size={23}/></div><div>LOCAL MODEL<span>BENCH</span></div></div><div className="workspace-label">YOUR WORKSPACE</div><nav>{pages.map(({name,icon:Icon})=><button key={name} className={page===name?'nav active':'nav'} onClick={()=>setPage(name)}><Icon size={19}/>{name}{name==='Run'&&progress&&<span className="live-dot" role="img" aria-label="a benchmark is running"/>}</button>)}</nav><div className="sidebar-bottom"><div className="privacy"><ShieldCheck size={17}/><div>Local by design<small>Your prompts stay on this PC</small></div></div><div className="version">Local Model Bench <span>1.8.0</span></div></div></aside>
 <main><header><div className="breadcrumb">Workspace <ChevronRight size={14}/><b>{page}</b></div><div className="header-actions">{updateState&&['available','downloading','ready'].includes(updateState.phase)&&<button className="connection update-pill" onClick={()=>setShowUpdate(true)}><span className="status-dot"/>{updateState.phase==='ready'?'Update ready':updateState.phase==='downloading'?'Downloading':'Update available'} — {updateState.info?.version}<ArrowRight size={13}/></button>}<button className={'connection '+(connected?'online':'')} onClick={()=>act('refresh',discover)}><span className="status-dot"/>{connected?'LM Studio connected':'LM Studio offline'}<RefreshCw size={13}/></button></div></header>
 <div className="content">{error&&<div role="alert" className="banner error"><span>{error}</span><button aria-label="Dismiss error" onClick={()=>setError('')}><X size={16}/></button></div>}{notice&&<div role="status" className="banner success"><span>{notice}</span><button aria-label="Dismiss notification" onClick={()=>setNotice('')}><X size={16}/></button></div>}
 {page==='Models'&&<><div className="page-heading"><div><div className="eyebrow">MODEL LIBRARY</div><h1>Choose models to benchmark</h1><p>Pick the local models you want to measure.</p></div><button onClick={()=>act('refresh',discover)} disabled={!!busy}><RefreshCw size={16}/>Refresh models</button></div>
 <div className="stats-row"><Stat label="Downloaded models" value={models.length.toString()} sub="Available through LM Studio"/><Stat label="Selected to compare" value={config.modelKeys.length.toString()} sub="Tested one model at a time"/><Stat label="Currently loaded" value={models.reduce((a,m)=>a+m.loaded_instances.length,0).toString()} sub="Other models can affect memory"/></div>
 {!connected&&<div className="panel connection-panel"><Server size={30}/><div><h3>Connect to LM Studio</h3><p>{connectionError||'Start your local server to discover downloaded models.'}</p><button className="primary" disabled={!!busy} onClick={()=>act('server',async()=>{setNotice(await api.startServer());await discover();})}>{busy==='server'?'Starting server…':'Start LM Studio Server'}</button></div></div>}
 <LibraryControls models={models} view={libraryView} onChange={setLibraryView}/>
 <div className="section-heading"><h2>Downloaded library <span>{shownModels.length} of {models.length}</span></h2><div className="button-row">{hiddenSelected>0&&<small>{hiddenSelected} selected model{hiddenSelected!==1?'s':''} hidden by filters</small>}<button className="text-button" disabled={!shownModels.length} onClick={()=>update('modelKeys',selectVisible(config.modelKeys,shownModels))}>{shownModels.length>0&&shownModels.every(m=>config.modelKeys.includes(m.key))?'Deselect shown':'Select shown'}</button>{config.modelKeys.length>0&&<button className="text-button" onClick={()=>update('modelKeys',[])}>Clear selection</button>}</div></div>
 <div className="model-grid">{shownModels.map(m=><button key={m.key} type="button" aria-pressed={config.modelKeys.includes(m.key)} className={'model-card '+(config.modelKeys.includes(m.key)?'selected':'')} onClick={()=>update('modelKeys',toggle(config.modelKeys,m.key))}><div className="model-card-top"><div className="model-icon"><Boxes size={23}/></div><span className={'checkbox '+(config.modelKeys.includes(m.key)?'checked':'')}>{config.modelKeys.includes(m.key)&&<Check size={14}/>}</span></div><h3>{m.display_name}</h3><div className="model-key">{m.key}</div><div className="model-tags"><Badge>{m.quantization?.name??'Unknown'}</Badge><Badge>{number(m.size_bytes>0?m.size_bytes/1e9:null)} GB</Badge><Badge tone={m.capabilities?.vision?'green':''}>{m.capabilities?.vision===true?'Vision':m.capabilities?.vision===false?'Text only':'Vision unknown'}</Badge>{m.loaded_instances.length>0&&<Badge tone="green">Loaded</Badge>}</div><div className="model-footer"><span>{number(m.max_context_length>0?m.max_context_length/1024:null,0)}k context</span><span>{m.capabilities?.reasoning?'Reasoning model':'Language model'}</span></div></button>)}</div>
 {models.length>0&&!shownModels.length&&<Empty title="No models match your filters">Try another quantization, clear your search, or use Reset view. Your selected models are preserved.</Empty>}
 {connected&&!models.length&&<Empty title="No downloaded models">Download a language model in LM Studio, then refresh this library.</Empty>}
 <div className="action-bar"><div><b>{config.modelKeys.length} model{config.modelKeys.length!==1?'s':''} selected</b><small>Choose tests and concurrency on the next screen.</small></div><button className="primary" disabled={!config.modelKeys.length} onClick={()=>setPage('Run')}>Configure benchmark <ArrowRight size={17}/></button></div></>}
 {page==='Benchmarks'&&<BenchmarkLibrary packs={snap?.packs??[]} busy={!!busy||!!progress} onUse={(selection,pack)=>{setConfig(c=>benchmarkConfig(c,selection,pack.name));setPage('Run');}} onChanged={async notice=>{await refresh();setNotice(notice);}}/>}
 {page==='Tests'&&<><div className="page-heading"><div><div className="eyebrow">TEST LIBRARY</div><h1>Custom tests</h1><p>Repeatable tasks, their objective checks, and the rubric used to grade them.</p></div><button className="primary" onClick={()=>setEditTest({...structuredClone(starterTests[0]),id:'',name:'New test',category:'Custom',prompt:'',rules:[],answerKey:''})}><Plus size={17}/>New test</button></div><div className="test-grid">{snap?.tests.map(t=><div className="panel test-card" key={t.id}><div className="section-heading"><Badge>{t.category}</Badge><small>v{t.version}</small></div><h3>{t.name}</h3><p>{t.prompt}</p><div className="test-footer"><span>{t.rules.length} objective checks</span><button onClick={()=>setEditTest(structuredClone(t))}>Edit test <ArrowRight size={14}/></button></div></div>)}</div></>}
 {page==='Run'&&<><div className="page-heading"><div><div className="eyebrow">BENCHMARK RUNNER</div><h1>Configure a benchmark</h1><p>Measure speed, concurrency, and response quality in one run.</p></div>{progress&&<Badge tone="green">Run active</Badge>}</div>
 {progress&&<div className="panel live-panel" aria-busy="true"><div className="section-heading"><div aria-live="polite"><div className="eyebrow">{progress.phase}</div><h3>{progress.message}</h3></div><button className="danger" onClick={()=>act('cancel',()=>api.cancel())}><Square size={14}/>Cancel run</button></div><div className="progress-track" role="progressbar" aria-label="Benchmark progress" aria-valuemin={0} aria-valuemax={progress.total||undefined} aria-valuenow={progress.total?progress.completed:undefined} aria-valuetext={progress.total?`${progress.completed} of ${progress.total} requests`:'Preparing'}><div style={{width:`${progress.total?Math.min(100,progress.completed/progress.total*100):3}%`}}/></div><div className="progress-meta"><span>{progress.completed} / {progress.total||'…'} requests</span><span>{progress.active} active</span></div>{run&&<div className="live-results">{run.samples.filter(s=>!s.warmup).slice(-4).map(s=><div key={s.id}><span>{s.testName}</span><Badge tone={s.status==='completed'?'green':'red'}>{s.status}</Badge><b>{number(s.metrics.generationTps)} <small>tok/s</small></b></div>)}</div>}<button className="text-button" onClick={()=>setPage('Results')}>View saved responses <ArrowRight size={14}/></button></div>}
 <fieldset disabled={!!progress||!!busy} className="run-fieldset"><div className="run-layout"><div className="run-main"><section className="panel"><div className="section-heading"><h2><span className="step">01</span>Choose your workload</h2></div><Field label="Run name"><input placeholder="e.g. Model comparison · office tasks" value={config.name} onChange={e=>update('name',e.target.value)}/></Field><div className="segmented">{(['combined','performance','quality'] as const).map(mode=><button className={config.mode===mode?'chosen':''} key={mode} onClick={()=>setConfig(c=>({...c,mode,...(mode==='performance'?{benchmark:undefined}:{})}))}>{mode==='combined'?'Speed + quality':mode==='performance'?'Speed only':'Quality only'}</button>)}</div>
 <FieldGroup label="Native multi-token prediction (MTP)" hint="Use the model’s built-in prediction heads. On requires confirmed support for every selected model; loaded settings are verified before testing."><div className="checks-row"><label><input aria-label="Enable native MTP" type="checkbox" checked={config.mtp==='on'} onChange={e=>update('mtp',e.target.checked?'on':'off')}/>Enable native MTP</label></div></FieldGroup>{config.mtp==='on'&&<><Field label="MTP draft tokens"><input aria-label="MTP draft tokens" type="number" min="1" max="8" value={config.mtpDraftTokens??2} onChange={e=>update('mtpDraftTokens',numOr(e.target.value,(config.mtpDraftTokens??2)))}/></Field><button onClick={()=>update('modelKeys',models.filter(m=>m.nativeMtp?.supported===true).map(m=>m.key))}>Select native MTP models</button>{models.some(m=>config.modelKeys.includes(m.key)&&m.nativeMtp?.supported!==true)&&<p className="hint amber">Some selected models lack confirmed native MTP support. Deselect them or turn MTP off.</p>}</>}
 <div className="field"><span id="vision-mode-label">Vision mode</span><div className="segmented" role="group" aria-labelledby="vision-mode-label">{(['auto','off','on'] as const).map(mode=><button key={mode} className={visionMode===mode?'chosen':''} aria-pressed={visionMode===mode} disabled={mode==='on'&&!visionCapable.length} title={mode==='on'&&!visionCapable.length?'No downloaded model reports vision capability to LM Studio.':undefined} onClick={()=>update('vision',mode)}>{({auto:'Auto',off:'Off / text-only',on:'On'} as const)[mode]}</button>)}</div><small>LM Studio has no load-time switch for a vision projector: it belongs to the model entry itself, so this chooses whether images are sent, and On additionally requires LM Studio to report the model as vision-capable.</small></div><p className="hint">{visionMode==='on'?'Images are sent as local data URLs only; a deterministic image smoke test runs alongside your text tests. Nothing leaves this machine.':visionMode==='off'?'No image is sent with any request. '+noProjectorToggleNote:'LM Studio’s own defaults; this app sends no image.'}</p>{visionMode==='on'&&<>{visionCapable.length>0&&<button onClick={()=>update('modelKeys',visionCapable.map(m=>m.key))}>Select vision-capable models</button>}{!!visionUnsupported.length&&<p className="hint amber">Vision is not confirmed for: {visionUnsupported.map(m=>m.display_name).join(', ')}. LM Studio reports no vision projector for these model entries. Deselect them, or choose Auto or Off to benchmark them as text-only — a separate non-vision copy of the model is not needed.</p>}</>}{visionMode!=='on'&&selectedModels.some(m=>visionSupport(m).supported===true)&&<p className="hint">A vision-capable model stays fully usable for text benchmarks; its projector remains loaded either way.</p>}
 <FieldGroup label="Models"><div className="selection-list">{models.map(m=><label key={m.key}><input type="checkbox" checked={config.modelKeys.includes(m.key)} onChange={()=>update('modelKeys',toggle(config.modelKeys,m.key))}/><span>{modelLabel(m)}</span></label>)}{!models.length&&<p>Connect to LM Studio from the Models screen first.</p>}</div></FieldGroup>
 {models.some(m=>m.loaded_instances.length>0)&&<p className="hint amber">Other models are loaded: {models.filter(m=>m.loaded_instances.length).map(m=>m.display_name).join(', ')}. These stay loaded and can affect memory and measurements.</p>}
 {config.mode!=='quality'&&<FieldGroup label="Performance prompt sizes" hint="Short ≈150, medium ≈2,000, long ≈6,000 tokens. Actual counts depend on the model; increase context if needed."><div className="checks-row">{['short','medium','long'].map(n=><label key={n}><input type="checkbox" checked={config.performanceLengths.includes(n)} onChange={()=>update('performanceLengths',toggle(config.performanceLengths,n))}/>{n}</label>)}</div></FieldGroup>}
 {config.mode!=='performance'&&<button onClick={()=>setConfig(c=>({...c,benchmark:undefined,mode:'quality',testIds:snap?.tests.filter(t=>t.category==='Accounting').map(t=>t.id)??[],maxTokens:1536,preset:'Custom'}))}>Use accounting suite</button>}
 {config.benchmark&&<div className="panel"><h3>{summaryFor(config.benchmark.packId,snap?.packs??[]).name}</h3><p>{config.benchmark.count} questions · seed {config.benchmark.seed}</p><button onClick={()=>setPage('Benchmarks')}>Change benchmark</button><button onClick={()=>update('benchmark',undefined)}>Use custom tests instead</button></div>}
 {config.mode!=='performance'&&!config.benchmark&&<FieldGroup label="Quality tests"><div className="selection-list">{snap?.tests.map(t=><label key={t.id}><input type="checkbox" checked={config.testIds.includes(t.id)} onChange={()=>update('testIds',toggle(config.testIds,t.id))}/><span>{t.name}</span><small>{t.category}</small></label>)}</div></FieldGroup>}</section>
 <section className="panel"><h2><span className="step">02</span>Set the pressure</h2><div className="presets">{['Quick','Balanced','Stress','Custom'].map(p=><button className={config.preset===p?'chosen':''} key={p} onClick={()=>setConfig(c=>({...c,preset:p,...(presets[p]??{})}))}><b>{p}</b><small>{p==='Quick'?'A first look':p==='Balanced'?'Everyday comparison':p==='Stress'?'Push the limits':'Your settings'}</small></button>)}</div><div className="form-grid"><Field label="Concurrent requests" hint="Comma-separated levels; e.g. 1, 2, 4, 8"><ConcurrencyInput value={config.concurrency} onChange={v=>setConfig(c=>({...c,concurrency:v,preset:'Custom'}))}/></Field><Field label="Waves per test"><input type="number" min="1" value={config.waves} onChange={e=>update('waves',numOr(e.target.value,config.waves))}/></Field><Field label="Maximum output tokens" hint="Also capped by each test's output limit. Includes reasoning."><input type="number" min="1" value={config.maxTokens} onChange={e=>update('maxTokens',numOr(e.target.value,config.maxTokens))}/></Field><Field label="Context length" hint="Per concurrent request. Parallel slots share one context budget, so the instance is loaded with this many tokens times the highest concurrency."><input type="number" min="512" step="512" value={config.contextLength} onChange={e=>update('contextLength',numOr(e.target.value,config.contextLength))}/></Field></div><details><summary>Model settings and timeouts</summary><div className="form-grid"><Field label="Temperature"><input type="number" min="0" max="1" step="0.1" value={config.temperature} onChange={e=>update('temperature',numOr(e.target.value,config.temperature))}/></Field><Field label="GPU offload"><select value={config.gpu} onChange={e=>update('gpu',e.target.value)}>{['auto','max','off','0.25','0.5','0.75'].map(v=><option key={v} value={v}>{v}</option>)}</select></Field><Field label="Reasoning" hint="Options are reported by every selected model. Model default works when a model exposes no reasoning controls."><select value={config.reasoning} onChange={e=>update('reasoning',e.target.value)}><option value="default">Model default</option>{invalidReasoning&&<option value={config.reasoning} disabled>{config.reasoning} (unavailable for this selection)</option>}{allowedReasoning.map(v=><option key={v} value={v}>{v}</option>)}</select></Field><Field label="Request timeout (seconds)"><input type="number" min="1" value={config.timeoutSec} onChange={e=>update('timeoutSec',numOr(e.target.value,config.timeoutSec))}/></Field></div></details></section>
 <section className="panel"><h2><span className="step">03</span>Choose how to grade</h2><div className="grade-info"><ShieldCheck size={22}/><div><b>Objective checks are always included</b><p>Known answers and explicit requirements are checked automatically. Writing quality and factual accuracy need review.</p></div></div><Field label="Optional local judge" hint="The judge runs after all speed measurements finish."><select value={config.judgeModel} onChange={e=>update('judgeModel',e.target.value)}><option value="">No local judge · objective checks only</option>{models.map(m=><option key={m.key} value={m.key}>{modelLabel(m)}</option>)}</select></Field><p className="hint">You can also copy any response with its grading prompt into another AI provider, then paste the grade back in Results.</p></section></div>
 <aside className="run-summary panel"><div className="eyebrow">RUN PREVIEW</div><h2>{config.preset} sweep</h2><div className="big-number">{number(total,0)}<span>measured requests</span></div><dl><dt>Models</dt><dd>{config.modelKeys.length}</dd><dt>Vision</dt><dd>{visionMode==='on'?'On · image tests included':visionMode==='off'?'Off · text-only':'Auto'}</dd><dt>Native MTP</dt><dd>{config.mtp==='on'?'On · '+(config.mtpDraftTokens??2)+' draft tokens':'Off'}</dd><dt>Tests per model</dt><dd>{totalTests}</dd><dt>Concurrency</dt><dd>{config.concurrency.join(' / ')||'—'}</dd><dt>Waves</dt><dd>{config.waves}</dd><dt>Server parallel slots</dt><dd>{config.concurrency.length?Math.max(...config.concurrency):'—'}</dd><dt>Context per request</dt><dd>{number(config.contextLength,0)}</dd><dt>Server context to load</dt><dd>{config.concurrency.length?number(serverContext(config.contextLength,Math.max(...config.concurrency)),0):'—'}</dd><dt>Warm-ups</dt><dd>1 per model</dd></dl><p className="hint">Each model runs separately. Completed results are saved as they arrive. Large sweeps can take substantial time.</p><button className="primary full" disabled={!connected||invalidReasoning||visionBlocked||!config.modelKeys.length||!total||(config.mtp==='on'&&config.modelKeys.some(key=>models.find(m=>m.key===key)?.nativeMtp?.supported!==true))} onClick={()=>act('start',started)}><Play size={17}/>Start benchmark</button></aside></div></fieldset></>}
 {page==='Results'&&<><div className="page-heading"><div><div className="eyebrow">BENCHMARK HISTORY</div><h1>{resultsView==='overview'?'Everything you have measured.':'See what holds up.'}</h1><p>{resultsView==='overview'?'Every saved run, pooled into one picture. Nothing is discarded and no measurement is recalculated; you choose which models and conditions to include.':'Results and responses save automatically to your local SQLite database. Filter comparisons below; exports include the full run.'}</p></div></div>
 <div className="segmented results-modes" role="group" aria-label="Results view">{([['run','Specific run'],['overview','All runs overview']] as const).map(([value,label])=><button key={value} className={resultsView===value?'chosen':''} aria-pressed={resultsView===value} onClick={()=>setResultsView(value)}>{label}</button>)}</div>
 {resultsView==='run'?<><div className="results-toolbar"><select aria-label="Saved run" value={runId} onChange={e=>{setRunId(e.target.value);setSampleId('')}}><option value="">Choose a saved run</option>{snap?.runs.map(r=><option key={r.id} value={r.id}>{r.config.name} · Vision {r.config.vision??'legacy/default'} · MTP {r.config.mtp??'legacy/default'} · {r.status} · {shortDate(r.created)}</option>)}</select><div className="button-row">{['html','csv','json','md'].map(f=><button key={f} disabled={!run} onClick={()=>act('export',async()=>{const p=await api.exportRun(runId,f);if(p)setNotice('Export saved: '+p);})}><Download size={14}/>{f==='html'?'Graph report':f.toUpperCase()}</button>)}</div></div>{run?<Results run={run} savedRuns={snap?.runs??[]} packs={snap?.packs??[]} models={models} busy={!!busy||!!progress} onSample={setSampleId} onGrade={judge=>act('grade',async()=>{await api.grade(run.id,judge);await refresh();})} onRetry={()=>act('retry',async()=>{setRunId(await api.retry(run.id));await refresh();setPage('Run');})}/>:<Empty title="Your first benchmark starts here">Choose models and start a run. Results and full responses will appear here automatically.</Empty>}</>
 :<HistoryPanel view={historyView} onChange={setHistoryView} signature={(snap?.runs??[]).map(r=>r.id+r.updated).join('|')} onOpenRun={id=>{setRunId(id);setSampleId('');setResultsView('run');}}/>}</>}
 {page==='Settings'&&<><div className="page-heading"><div><div className="eyebrow">PREFERENCES</div><h1>Settings</h1><p>Connection, timeouts, and the instructions your judge follows.</p></div></div><div className="settings-layout"><section className="panel"><h2>LM Studio connection</h2><Field label="Local server address"><input value={settingsDraft.baseUrl} onChange={e=>setSettingsDraft(s=>({...s,baseUrl:e.target.value}))}/></Field><Field label="API token (optional)" hint={settingsDraft.tokenConfigured?'A token is saved. Leave this blank to keep it, or type a new one to replace it.':'Stored using Windows encryption. Never included in exports, and never sent back to this window.'}><input type="password" autoComplete="off" placeholder={settingsDraft.tokenConfigured?'Saved':'No token'} value={tokenDraft} onChange={e=>{setTokenDraft(e.target.value);setClearToken(false);}}/></Field>{settingsDraft.tokenConfigured&&<button type="button" className="subtle" aria-pressed={clearToken} onClick={()=>{setClearToken(c=>!c);setTokenDraft('');}}>{clearToken?'Saved token will be removed':'Remove saved token'}</button>}<Field label="LM Studio command-line tool"><input value={settingsDraft.lmsPath} onChange={e=>setSettingsDraft(s=>({...s,lmsPath:e.target.value}))}/></Field><div className="form-grid"><Field label="Default request timeout (seconds)"><input type="number" value={settingsDraft.timeoutSec} onChange={e=>setSettingsDraft(s=>({...s,timeoutSec:+e.target.value}))}/></Field><Field label="Model load timeout (seconds)"><input type="number" value={settingsDraft.loadTimeoutSec} onChange={e=>setSettingsDraft(s=>({...s,loadTimeoutSec:+e.target.value}))}/></Field></div><button className="primary" disabled={!!progress||!!busy} onClick={()=>act('save',async()=>{await api.saveSettings({...settingsDraft,token:clearToken?'':(tokenDraft||undefined)});const s=await refresh();setSettingsDraft(s.settings);setTokenDraft('');setClearToken(false);await discover();setNotice('Settings saved.');})}>Save settings</button></section><section className="panel"><h2>Judge instructions</h2><p className="hint">Applied to local grading and copied grading packages. Each test also has its own rubric. Saved runs keep their original grading instructions.</p><textarea rows={10} value={settingsDraft.judgePrompt} onChange={e=>setSettingsDraft(s=>({...s,judgePrompt:e.target.value}))}/><h2 className="mt">Updates</h2><p className="hint">Off by default. With no repository named this app makes no outbound request of any kind; naming one lets it ask GitHub for that repository's latest published release, and nothing is downloaded or run until you press the buttons yourself. Save settings before checking.</p>
<Field label="GitHub repository" hint="owner/name, for example your-account/local-model-bench. Leave blank to keep update checks off."><input placeholder="owner/name" autoComplete="off" value={settingsDraft.updateRepo} onChange={e=>setSettingsDraft(s=>({...s,updateRepo:e.target.value,...(e.target.value.trim()?{}:{updateCheck:false})}))}/></Field>
<div className="checks-row plain"><label><input type="checkbox" aria-label="Check for updates at startup" checked={settingsDraft.updateCheck} disabled={!settingsDraft.updateRepo.trim()} onChange={e=>setSettingsDraft(s=>({...s,updateCheck:e.target.checked}))}/>Check when the app starts</label></div>
<div className="button-row"><button disabled={!!busy||!snap?.settings.updateRepo.trim()} onClick={()=>act('update',async()=>{setUpdateState(await api.checkUpdate());setShowUpdate(true);})}><RefreshCw size={15}/>Check now</button><small>Installed version {updateState?.current||'—'}{updateState?.checked?' · last checked '+new Date(updateState.checked).toLocaleString():''}</small></div>
<h2 className="mt">Local data</h2><p className="hint path">{snap?.dataPath}</p><button onClick={()=>act('folder',()=>api.openData())}><FolderOpen size={16}/>Open data folder</button><p className="hint">Run history, test versions, and full responses are stored locally. No analytics and no model downloads. The only request this app can make beyond your LM Studio server is the update check above, and only once you have named a repository.</p></section></div></>}
 <footer>LOCAL MODEL BENCH <span>Local benchmarks for LM Studio.</span></footer></div></main>
 {editTest&&<TestEditor test={editTest} onClose={()=>setEditTest(null)} onSave={t=>act('test',async()=>{await api.saveTest(t);await refresh();setEditTest(null);setNotice('Test saved. Existing runs keep their original version.');})} onDelete={()=>act('delete',async()=>{await api.deleteTest(editTest.id);update('testIds',config.testIds.filter(x=>x!==editTest.id));await refresh();setEditTest(null);})} busy={!!busy}/>}
 {selectedSample&&run&&<SampleDetail sample={selectedSample} onClose={()=>setSampleId('')} onCopy={async()=>{const result=await api.copyPackage(run.id,selectedSample.id);setNotice(result.copied?'Grading package copied. Paste it into your preferred AI provider.':'Clipboard access is unavailable. Copy the selected grading package below.');return result;}} onImport={(raw,judge)=>act('import',async()=>{await api.importGrade(run.id,selectedSample.id,raw,judge);setRun(await api.getRun(run.id));setNotice('External grade saved.');})} busy={!!busy}/>}
 {showUpdate&&updateState&&<UpdateDialog state={updateState} busy={!!busy} onClose={()=>setShowUpdate(false)} onDownload={()=>act('download',async()=>{setUpdateState(await api.downloadUpdate());})} onInstall={()=>act('install',()=>api.installUpdate())}/>}
 {busy&&<div className="busy-indicator"><span className="spinner"/>{busy==='start'?'Preparing run…':busy==='server'?'Starting LM Studio…':'Working…'}</div>}
 </div>;
}
function UpdateDialog({state,busy,onClose,onDownload,onInstall}:{state:UpdateState;busy:boolean;onClose:()=>void;onDownload:()=>void;onInstall:()=>void}){
 const dialogRef=useModalDialog<HTMLElement>(onClose);
 const info=state.info,percent=state.total?Math.min(100,state.received/state.total*100):0;
 return <div className="modal-backdrop"><section ref={dialogRef} tabIndex={-1} className="modal" role="dialog" aria-modal="true" aria-label="Update">
  <div className="modal-header"><div><div className="eyebrow">UPDATE</div><h2>{info?`Version ${info.version}`:state.phase==='checking'?'Checking…':'No newer release'}</h2><small>Installed: {state.current||'unknown'}</small></div><button aria-label="Close update" onClick={onClose}><X size={19}/></button></div>
  <div className="modal-body">{state.error&&<div role="alert" className="banner error">{state.error}</div>}
   {info?<>
    <p className="hint">{info.published?'Published '+new Date(info.published).toLocaleString():'Publication date unavailable'}</p>
    <details open><summary>What changed</summary><pre>{info.notes||'This release published no notes.'}</pre></details>
    <dl className="update-facts"><dt>Installer</dt><dd>{info.assetName}</dd><dt>Size</dt><dd>{number(info.assetSize/1e6)} MB</dd><dt>Checksum published with the release</dt><dd>{info.publishedSha256??'None published'}</dd>{state.sha256&&<><dt>Checksum of the file downloaded</dt><dd>{state.sha256}</dd></>}</dl>
    {state.phase==='downloading'&&<><div className="progress-track" role="progressbar" aria-label="Update download" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(percent)}><div style={{width:percent+'%'}}/></div><div className="progress-meta"><span>{number(state.received/1e6)} / {number(state.total/1e6)} MB</span><span>{number(percent,0)}%</span></div></>}
    {state.phase==='ready'&&(state.verified?<div className="banner success">The downloaded installer matches the checksum published with this release.</div>:<p className="hint amber">This release published no checksum, so nothing could vouch for the download. Compare the checksum above against the one you published before installing.</p>)}
    <p className="hint">Installing closes Local Model Bench and runs the installer, which asks before it replaces anything. Saved runs, tests, and settings stay where they are.</p>
   </>:<p className="hint">{state.phase==='checking'?'Asking GitHub for the latest published release.':'You are running the newest published release.'}</p>}</div>
  <div className="modal-footer"><button onClick={onClose}>Close</button>
   {info&&state.phase!=='ready'&&<button className="primary" disabled={busy||state.phase==='downloading'} onClick={onDownload}><Download size={16}/>{state.phase==='downloading'?'Downloading…':'Download '+info.version}</button>}
   {state.phase==='ready'&&<button className="primary" disabled={busy} onClick={onInstall}><ArrowRight size={16}/>Close and install {info?.version}</button>}
  </div></section></div>;
}
// Mirrors validateConfig's bounds so the preview and the main process agree. Without
// this "x" became [NaN] and the preview read "NaN measured requests", while "-5" stayed
// truthy enough to leave Start enabled and only failed once it reached validation.
function ConcurrencyInput({value,onChange}:{value:number[];onChange:(v:number[])=>void}){
 const [text,setText]=useState(value.join(', '));
 useEffect(()=>setText(value.join(', ')),[value.join(',')]);
 const entered=text.split(',').map(x=>x.trim()).filter(x=>x!=='');
 const rejected=entered.filter(x=>{const n=Number(x);return !Number.isInteger(n)||n<1||n>256;});
 const commit=()=>onChange(entered.map(Number).filter(n=>Number.isInteger(n)&&n>=1&&n<=256));
 return <>
  <input aria-label="Concurrency levels" aria-invalid={rejected.length>0} value={text} onChange={e=>setText(e.target.value)} onBlur={commit}/>
  {rejected.length>0&&<small role="alert" className="hint amber">Ignored: {rejected.join(', ')}. Each level is a whole number from 1 to 256.</small>}
 </>;
}
function Stat({label,value,sub}:{label:string;value:string;sub:string}){return <div className="stat"><span>{label}</span><b>{value}</b><small>{sub}</small></div>}
function GpuPanel({run}:{run:Run}){
 const gpu=run.gpu,stats=gpu?.stats;
 if(!gpu||!gpu.available||!stats)return <section className="panel"><h2>GPU thermals</h2><p className="hint">{gpu?.note||'GPU telemetry was not recorded for this run. Runs saved before thermal recording was added have no readings.'}</p></section>;
 return <section className="panel"><div className="section-heading"><div><h2>GPU thermals</h2><p className="hint">{gpu.device} · {stats.samples} readings · sampled every {gpu.intervalMs} ms</p></div></div>
  <div className="stats-row four"><Stat label="Peak hot spot" value={number(stats.tempHotSpot?.max)+' °C'} sub="Highest reading during the run"/><Stat label="Average hot spot" value={number(stats.tempHotSpot?.avg)+' °C'} sub="Includes loading and idle gaps"/><Stat label="Peak core" value={number(stats.tempCore?.max)+' °C'} sub="Edge sensor"/><Stat label="Average board power" value={number(stats.power?.avg)+' W'} sub="Package power draw"/></div>
  <div className="legend chart-legend" dangerouslySetInnerHTML={{__html:gpuLegendHtml()}}/>
  <div className="gpu-chart" dangerouslySetInnerHTML={{__html:gpuTimelineChart(gpu.series)}}/>
  <div className="table-scroll"><table><thead><tr>{['Measurement','Minimum','Average','Maximum','Unit'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{gpuMetrics.map(key=>{const stat=stats[key];return <tr key={key}><td>{gpuMetricLabels[key]}</td><td>{number(stat?.min)}</td><td>{number(stat?.avg)}</td><td>{number(stat?.max)}</td><td>{gpuMetricUnits[key]}</td></tr>;})}<tr><td>Memory in use</td><td>—</td><td>—</td><td>{number(stats.memoryUsedMax,0)}</td><td>MB</td></tr></tbody></table></div>
  <p className="hint">{gpu.note} {gpu.seriesNote}</p></section>;
}
function Results({run,savedRuns,packs,models,busy,onSample,onGrade,onRetry}:{run:Run;savedRuns:Snapshot['runs'];packs:Snapshot['packs'];models:Model[];busy:boolean;onSample:(id:string)=>void;onGrade:(judge:string)=>void;onRetry:()=>void}){
 const [filter,setFilter]=useState(''),[judge,setJudge]=useState('');
 const [comparison,setComparison]=useState({...defaultComparisonFilter}),[savedProfiles,setSavedProfiles]=useState<Record<string,ModelProfile>>({}),[inspect,setInspect]=useState('');
 useEffect(()=>{let alive=true;api.modelProfiles().then(v=>{if(alive)setSavedProfiles(v);}).catch(console.error);return()=>{alive=false;};},[]);
 // Filtering and summarising walk every saved response, so they run when the run or the comparison changes
 // rather than on every keystroke in the response filter.
 const profiles=useMemo(()=>profilesFor(run,models,savedProfiles),[run,models,savedProfiles]);
 const matching=useMemo(()=>Object.keys(profiles).filter(key=>matchesProfile(key,profiles[key],comparison)),[profiles,comparison]);
 const keys=useMemo(()=>matching.filter(key=>!comparison.excluded.includes(key)),[matching,comparison]);
 const filteredRun=useMemo(()=>({...run,config:{...run.config,modelKeys:keys},samples:run.samples.filter(s=>keys.includes(s.modelKey)),waves:run.waves.filter(w=>keys.includes(w.modelKey))}),[run,keys]);
 const rows=useMemo(()=>summaries(filteredRun),[filteredRun]);
 const samples=useMemo(()=>filteredRun.samples.filter(s=>!s.warmup),[filteredRun]);
 const good=useMemo(()=>samples.filter(s=>s.status==='completed'),[samples]);
 return <><div className="section-heading"><div className="button-row"><Badge tone={run.status==='completed'?'green':run.status==='failed'?'red':''}>{run.status}</Badge><small>{new Date(run.created).toLocaleString()}</small>{run.config.retryOf&&<Badge>Retry run</Badge>}</div><button disabled={busy} onClick={onRetry}>Retry failed requests</button></div>{run.error&&<div className="banner error">{run.error}</div>}
 <ComparisonControls profiles={profiles} matching={matching} visible={keys} filter={comparison} onChange={setComparison} inspect={inspect} onInspect={setInspect} onSave={async(key,p)=>{await api.saveModelProfile(key,p);setSavedProfiles(await api.modelProfiles());}}/>
 <div className="stats-row four"><Stat label="Generation / request" value={number(average(good.map(s=>s.metrics.generationTps)))} sub="tokens / second · successful requests"/><Stat label="Estimated prefill" value={number(average(good.map(s=>s.metrics.prefillTps)))} sub="tokens / second · client-timed estimate"/><Stat label="Completed requests" value={`${good.length} / ${samples.length}`} sub="Warm-ups excluded"/><Stat label="Objective checks" value={number(average(good.map(s=>s.objective.score)))} sub="out of 100 · scored requests only"/></div>
 {run.tests.some(t=>t.benchmark)?<BenchmarkResults run={filteredRun} savedRuns={savedRuns} packs={packs}/>:<ChartsPanel run={filteredRun} onModel={setInspect}/>}
 <GpuPanel run={run}/>
 {inspect&&<section className="panel"><h2>{inspect}</h2><p className="hint">Saved responses for this model in the current comparison.</p><div className="response-list">{samples.filter(s=>s.modelKey===inspect).map(s=><button key={s.id} onClick={()=>onSample(s.id)}>{s.testName} · concurrency {s.concurrency} · {s.status} · View response</button>)}</div><button onClick={()=>setInspect('')}>Close model inspection</button></section>}
 <p className="hint">Prefill is an estimate: cache reuse and stream buffering are not observable. Generation includes reasoning tokens when reported. Scores shown above average only applicable checks and are not a general intelligence ranking. Tail latency from small samples is unstable.</p>
 <section className="panel"><h2>Model comparison</h2><div className="table-scroll"><table><thead><tr>{['Model / test','Concurrency','Gen tok/s','Prefill est.','Total tok/s','Median / p95','Failures','Objective','Local judge','External','GPU hot spot avg / peak'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r.modelKey+'|'+r.testId+'|'+r.concurrency}><td><b>{r.model}</b><small>{r.modelKey}</small><small>{r.test}</small></td><td>{r.concurrency}</td><td>{number(r.generationTps)}</td><td>{number(r.estimatedPrefillTps)}</td><td>{number(r.throughput)}</td><td>{number(r.medianMs===null?null:r.medianMs/1000)} / {number(r.p95Ms===null?null:r.p95Ms/1000)} s</td><td>{r.failures}/{r.requests}</td><td>{number(r.objective)}</td><td>{number(r.localJudge)}</td><td>{number(r.externalJudge)}</td><td>{number(r.gpuHotSpotAvg)} / {number(r.gpuHotSpotMax)} °C</td></tr>)}</tbody></table></div>{!rows.length&&<p className="hint">Measurements will appear as requests finish.</p>}</section>
 <section className="panel"><div className="section-heading"><h2>Response explorer</h2><input className="search" aria-label="Filter responses" placeholder="Filter model, test, or status…" value={filter} onChange={e=>setFilter(e.target.value)}/></div><div className="grade-toolbar"><select aria-label="Judge model" value={judge} onChange={e=>setJudge(e.target.value)}><option value="">Choose a local judge…</option>{models.map(m=><option key={m.key} value={m.key}>{modelLabel(m)}</option>)}</select><button disabled={busy||!judge||!good.length} onClick={()=>onGrade(judge)}>Grade all run quality responses</button></div><div className="response-list">{samples.filter(s=>(s.modelKey+' '+s.testName+' '+s.status).toLowerCase().includes(filter.toLowerCase())).map(s=><button key={s.id} onClick={()=>onSample(s.id)}><div><b>{s.testName}</b><small>{s.modelKey} · concurrency {s.concurrency} · wave {s.wave+1}{s.retryOf?' · retry':''}</small></div><Badge tone={s.status==='completed'?'green':'red'}>{s.status}</Badge><span>{number(s.metrics.generationTps)} tok/s</span><ChevronRight size={16}/></button>)}</div></section>
 <details className="panel"><summary>Run settings, effective model configuration, and log</summary><pre>{JSON.stringify({config:run.config,models:run.modelInfo,environment:run.environment},null,2)}</pre><pre>{run.logs.join('\n')||'No additional messages.'}</pre></details></>;
}
function TestEditor({test,onClose,onSave,onDelete,busy}:{test:TestCase;onClose:()=>void;onSave:(t:TestCase)=>void;onDelete:()=>void;busy:boolean}){
 const [t,setT]=useState(test);const change=(patch:Partial<TestCase>)=>setT(v=>({...v,...patch}));const updateRule=(i:number,patch:Partial<Rule>)=>change({rules:t.rules.map((r,j)=>i===j?{...r,...patch}:r)});
 const dialogRef=useModalDialog<HTMLElement>(onClose);
 return <div className="modal-backdrop"><section ref={dialogRef} tabIndex={-1} className="modal wide" role="dialog" aria-modal="true" aria-label="Edit test"><div className="modal-header"><div><div className="eyebrow">TEST EDITOR</div><h2>{t.name||'New test'}</h2></div><button aria-label="Close test editor" onClick={onClose}><X size={19}/></button></div><div className="modal-body"><div className="form-grid"><Field label="Name"><input value={t.name} onChange={e=>change({name:e.target.value})}/></Field><Field label="Category"><input value={t.category} onChange={e=>change({category:e.target.value})}/></Field></div><Field label="Prompt"><textarea rows={7} value={t.prompt} onChange={e=>change({prompt:e.target.value})}/></Field><div className="form-grid"><Field label="Answer key (optional)"><textarea rows={3} value={t.answerKey} onChange={e=>change({answerKey:e.target.value})}/></Field><Field label="Output token limit"><input type="number" value={t.maxTokens} onChange={e=>change({maxTokens:+e.target.value})}/></Field></div><Field label="Grading rubric"><textarea rows={3} value={t.rubric} onChange={e=>change({rubric:e.target.value})}/></Field><div className="section-heading"><h3>Objective checks</h3><button onClick={()=>change({rules:[...t.rules,{id:crypto.randomUUID(),label:'New check',type:'contains',expected:'',weight:1}]})}><Plus size={14}/>Add check</button></div><p className="hint">These checks measure explicit requirements. They do not establish the accuracy of an open-ended report.</p>{t.rules.map((r,i)=><div className="rule" key={r.id}><div className="rule-top"><input aria-label="Check label" value={r.label} onChange={e=>updateRule(i,{label:e.target.value})}/><select aria-label="Check type" value={r.type} onChange={e=>updateRule(i,{type:e.target.value as Rule['type']})}>{Object.entries({contains:'Contains text',heading:'Standalone heading',exact:'Exact answer',number:'Numeric answer',json:'Valid JSON','json-equal':'Exact JSON content',field:'JSON field',words:'Word count',lines:'Line count'}).map(([v,label])=><option key={v} value={v}>{label}</option>)}</select><button aria-label="Remove check" onClick={()=>change({rules:t.rules.filter((_,j)=>i!==j)})}><Trash2 size={15}/></button></div><div className="form-grid">{!['json','words'].includes(r.type)&&<Field label={r.type==='lines'?'Required line prefix (optional)':'Expected value'}><input value={r.expected??''} onChange={e=>updateRule(i,{expected:e.target.value})}/></Field>}{r.type==='field'&&<Field label="Field path" hint="Use dots for nested fields, e.g. result.count"><input value={r.path??''} onChange={e=>updateRule(i,{path:e.target.value})}/></Field>}{['words','lines'].includes(r.type)&&<><Field label="Minimum"><input type="number" value={r.min??0} onChange={e=>updateRule(i,{min:+e.target.value})}/></Field><Field label="Maximum"><input type="number" value={r.max??100} onChange={e=>updateRule(i,{max:+e.target.value})}/></Field></>}{r.type==='number'&&<Field label="Numeric tolerance"><input type="number" value={r.tolerance??0} onChange={e=>updateRule(i,{tolerance:+e.target.value})}/></Field>}<Field label="Weight"><input type="number" min="0.1" step="0.1" value={r.weight} onChange={e=>updateRule(i,{weight:+e.target.value})}/></Field></div></div>)}</div><div className="modal-footer">{t.id&&<button className="danger" disabled={busy} onClick={onDelete}><Trash2 size={15}/>Delete test</button>}<button onClick={onClose}>Cancel</button><button className="primary" disabled={busy} onClick={()=>onSave(t)}>Save test</button></div></section></div>;
}
function SampleDetail({sample:s,onClose,onCopy,onImport,busy}:{sample:Sample;onClose:()=>void;onCopy:()=>Promise<{copied:boolean;text:string}>;onImport:(raw:string,judge:string)=>void;busy:boolean}){const [raw,setRaw]=useState(''),[judge,setJudge]=useState(''),[packageText,setPackageText]=useState(''),[copying,setCopying]=useState(false),[copyError,setCopyError]=useState('');const dialogRef=useModalDialog<HTMLElement>(onClose);return <div className="modal-backdrop"><section ref={dialogRef} tabIndex={-1} className="modal wide" role="dialog" aria-modal="true" aria-label="Response detail"><div className="modal-header"><div><div className="eyebrow">RESPONSE DETAIL</div><h2>{s.testName}</h2><small>{s.modelKey} · concurrency {s.concurrency}</small></div><button aria-label="Close response" onClick={onClose}><X size={19}/></button></div><div className="modal-body"><div className="button-row"><Badge tone={s.status==='completed'?'green':'red'}>{s.status}</Badge>{s.possibleTruncation&&<Badge tone="amber">Output limit reached</Badge>}<span>{number(s.metrics.generationTps)} generation tok/s</span><span>{number(s.metrics.prefillTps)} estimated prefill tok/s</span>{s.gpu?.tempHotSpot&&<span>{number(s.gpu.tempHotSpot.max)} °C peak hot spot{s.gpu.exact?'':' (nearest reading)'}</span>}</div>{s.error&&<div className="banner error">{s.error}</div>}<details><summary>Exact prompt</summary><pre>{s.prompt}</pre></details><h3>Model response</h3><pre className="response-text">{s.output||'(No final answer received)'}</pre>{s.reasoning&&<details><summary>Reasoning output</summary><pre>{s.reasoning}</pre></details>}<h3>Objective score: {number(s.objective.score)} / 100</h3>{s.objective.checks.map(c=><div className="check-result" key={c.id}><Badge tone={c.passed?'green':'red'}>{c.passed?'PASS':'FAIL'}</Badge><div><b>{c.label}</b><small>{c.detail} · weight {c.weight}</small></div></div>)}{!s.objective.checks.length&&<p className="hint">No applicable objective checks were scored.</p>}<h3>Model and external grades</h3>{s.grades.map((g,i)=><div className="grade-card" key={g.source+'|'+g.judge+'|'+g.created+'|'+i}><div className="section-heading"><Badge>{g.source}</Badge><b>{number(g.score)} / 100</b></div><small>{g.judge} · rubric v{g.rubricVersion} · {new Date(g.created).toLocaleString()}</small><p>{g.summary}</p>{g.criteria.map(c=><p key={c.name}><b>{c.name}: {c.score}</b> — {c.reason}</p>)}</div>)}<button onClick={async()=>{setCopying(true);try{const result=await onCopy();setPackageText(result.text);}catch(e){setCopyError((e as Error).message);}finally{setCopying(false);}}} disabled={busy||copying}><Copy size={16}/>{copying?'Copying…':'Copy grading package'}</button>{copyError&&<p className="hint amber">{copyError}</p>}{packageText&&<details open><summary>Grading package · select and copy</summary><p className="hint">Click the text to select it, then press Ctrl+C. Paste it into your chosen AI provider.</p><textarea aria-label="Grading package text" rows={8} readOnly value={packageText} onFocus={e=>e.currentTarget.select()}/></details>}<details><summary>Paste an external grade</summary><p className="hint">Paste the JSON grade returned using the copied package. It must contain correctness, completeness, clarity, and instruction_following scores and reasons.</p><Field label="Provider / model name"><input placeholder="Name the reviewer" value={judge} onChange={e=>setJudge(e.target.value)}/></Field><textarea aria-label="External grade JSON" rows={6} value={raw} onChange={e=>setRaw(e.target.value)} placeholder='{"criteria":[...],"summary":"..."}'/><button className="primary" disabled={busy||!raw.trim()} onClick={()=>onImport(raw,judge)}>Save external grade</button></details><details><summary>Timing details and raw statistics</summary><pre>{JSON.stringify({metrics:s.metrics,gpu:s.gpu??'Not recorded',rawStats:s.rawStats,retryOf:s.retryOf},null,2)}</pre></details></div></section></div>}
createRoot(document.getElementById('root')!).render(<App/>);

